// Local, replayable paint actions. One gesture is one coat, including jelly.
export const SIZE=512;
export const palette=[['Tomato','#ba2e1f'],['Oxblood','#4d1524'],['Ink','#171918'],['Cream','#e8ddc3'],['Milk','#f5efe3'],['Ballet','#d8a7ac'],['Cobalt','#2343af'],['Moss','#626847'],['Espresso','#4a3028'],['Silver','#b4b8b3']].map(([name,color],number)=>({name,color,number:number+1}));
export const materials=['cream','jelly','pearl','chrome','glitter','magnetic','matte','gloss'];
export const toolNames=['brush','liner','dot','fan','pick','erase'];
export const objects=['star','spark','dot','heart','pearl'];
export function canvas(){const c=document.createElement('canvas');c.width=c.height=SIZE;return c;}
function copy(c){const d=canvas();d.getContext('2d').drawImage(c,0,0);return d;}
export function createSurface(){const paint=canvas(),finish=canvas(),detail=canvas();return {canvas:paint,ctx:paint.getContext('2d',{willReadFrequently:true}),finish,fctx:finish.getContext('2d'),detail,dctx:detail.getContext('2d'),particles:[],objects:[]};}
export function startLayer(n,a){return {paint:copy(n.canvas),finish:copy(n.finish),detail:copy(n.detail),layer:canvas(),mask:canvas(),ink:canvas(),particles:n.particles.slice(),objects:n.objects.slice(),deposits:[],count:0,action:a};}
function random(seed){let x=seed|0;return ()=>{x^=x<<13;x^=x>>>17;x^=x<<5;return (x>>>0)/4294967296;};}
function footprint(ctx,p,tool,color,soft=false){ctx.save();ctx.fillStyle=color;const ry=tool==='brush'?p.r*.6:p.r;if(soft){const g=ctx.createRadialGradient(p.x,p.y,p.r*.1,p.x,p.y,p.r);g.addColorStop(0,color);g.addColorStop(1,'transparent');ctx.fillStyle=g;}ctx.beginPath();ctx.ellipse(p.x,p.y,p.r,ry,0,0,Math.PI*2);ctx.fill();ctx.restore();}
function drawObject(ctx,p,a){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(a.rotation||0);const r=p.r;ctx.fillStyle=a.pigment||palette[a.color].color;ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=Math.max(2,r*.12);ctx.lineJoin='round';ctx.beginPath();if(a.object==='star'||a.object==='spark'){const count=a.object==='star'?5:4;for(let k=0;k<count*2;k++){const angle=-Math.PI/2+k*Math.PI/count;const radius=k%2?r*.4:r;k?ctx.lineTo(Math.cos(angle)*radius,Math.sin(angle)*radius):ctx.moveTo(Math.cos(angle)*radius,Math.sin(angle)*radius);}ctx.closePath();ctx.fill();}else if(a.object==='heart'){ctx.moveTo(0,r*.85);ctx.bezierCurveTo(-r*1.7,-r*.25,-r*.65,-r*1.45,0,-r*.55);ctx.bezierCurveTo(r*.65,-r*1.45,r*1.7,-r*.25,0,r*.85);ctx.stroke();}else{ctx.arc(0,0,r*(a.object==='pearl'?.75:.55),0,Math.PI*2);if(a.object==='pearl'){ctx.fillStyle='#e5ddc6';ctx.strokeStyle='#aa9981';ctx.lineWidth=1.7;ctx.fill();ctx.stroke();ctx.beginPath();ctx.arc(-r*.22,-r*.24,r*.17,0,Math.PI*2);ctx.fillStyle='#fffaf0';}ctx.fill();}ctx.restore();}
export function addStamp(layer,p){const a=layer.action,paint=layer.layer.getContext('2d'),mask=layer.mask.getContext('2d'),ink=layer.ink.getContext('2d');const pigment=a.pigment||palette[a.color].color;const index=materials.indexOf(a.material);if(a.tool==='pick'){if(layer.count===0)drawObject(ink,p,a);layer.count++;return;}
paint.save();if(a.legacy)paint.globalAlpha=a.legacyClear?0:a.tool==='brush'?.30*(a.blend||1):.96;footprint(paint,p,a.tool,pigment,a.tool==='fan');paint.restore();footprint(mask,p,a.tool,`rgb(${(index+1)*28},0,0)`);
if(a.material==='glitter'&&a.tool!=='erase'){const rng=random((a.seed||1)+layer.count*1376312589);const count=a.tool==='fan'?4:a.tool==='dot'?10:3;for(let i=0;i<count&&layer.deposits.length<600;i++){const angle=rng()*Math.PI*2,dist=Math.sqrt(rng())*p.r,px=p.x+Math.cos(angle)*dist,py=p.y+Math.sin(angle)*dist*(a.tool==='brush'?.6:1);if(px<0||py<0||px>SIZE||py>SIZE)continue;const r=.9+rng()*2.3;ink.save();ink.translate(px,py);ink.rotate(rng()*Math.PI);ink.globalAlpha=.65+rng()*.35;ink.fillStyle=rng()>.48?'#f4e9c7':rng()>.45?pigment:'#b5aaa0';ink.fillRect(-r,-r*.6,r*2,r*1.2);ink.restore();layer.deposits.push({x:px,y:py,r});}}
layer.count++;}
export function applyLayer(n,layer){const a=layer.action;for(const [ctx,base] of [[n.ctx,layer.paint],[n.fctx,layer.finish],[n.dctx,layer.detail]]){ctx.clearRect(0,0,SIZE,SIZE);ctx.drawImage(base,0,0);}if(a.tool==='erase'){for(const ctx of [n.ctx,n.fctx,n.dctx]){ctx.save();ctx.globalCompositeOperation='destination-out';ctx.drawImage(layer.layer,0,0);ctx.restore();}const removed=o=>a.points.some(p=>Math.hypot(o.x-p.x,o.y-p.y)<p.r+o.r*.5);n.particles=layer.particles.filter(p=>!removed(p));n.objects=layer.objects.filter(o=>!removed(o));}else if(a.tool==='pick'){n.dctx.drawImage(layer.ink,0,0);n.objects=[...layer.objects,{...a.points[0],object:a.object}];}else{const opacity=a.legacy?1:a.material==='jelly'?.32:a.material==='glitter'?.075:a.tool==='liner'||a.tool==='dot'?.97:.83;n.ctx.save();n.ctx.globalAlpha=opacity*(a.tool==='fan'?.34:1);n.ctx.drawImage(layer.layer,0,0);n.ctx.restore();n.fctx.drawImage(layer.mask,0,0);n.dctx.drawImage(layer.ink,0,0);n.particles=[...layer.particles,...layer.deposits].slice(-6000);}
}
export function replay(n,actions){for(const ctx of [n.ctx,n.fctx,n.dctx])ctx.clearRect(0,0,SIZE,SIZE);n.particles=[];n.objects=[];for(const a of actions){const layer=startLayer(n,a);a.points.forEach(p=>addStamp(layer,p));applyLayer(n,layer);} }
export function migrate(data){if(!data||![1,2].includes(data.v)||!Array.isArray(data.nails)||data.nails.length!==10)return null;if(data.v===2)return data;const old=['#ba2e1f','#4d1524','#171918','#ece4ce','#a6aaa8','#183ab4','#bacb35','#ffffff'],map=[0,1,2,3,9,6,7,4];return {...data,v:2,colorIndex:map[data.colorIndex]??0,material:'cream',nails:data.nails.map(actions=>actions.map((a,i)=>({...a,legacy:true,legacyClear:a.color===7,pigment:old[a.color],color:map[a.color]??0,material:a.color===4?'chrome':a.color===7?'gloss':'cream',seed:i+1}))),object:'star'};}
export function validAction(a){return a&&toolNames.includes(a.tool)&&materials.includes(a.material)&&Number.isInteger(a.color)&&a.color>=0&&a.color<palette.length&&(!a.pigment||/^#[0-9a-f]{6}$/i.test(a.pigment))&&Array.isArray(a.points)&&a.points.length<=20000&&a.points.every(p=>Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.r>0&&p.r<150)&& (a.tool!=='pick'||objects.includes(a.object));}
